# patterned alt / aria strings: "<Name>, image N", "<Name>: previous image", etc.
import re
def pattern(s):
    m=re.fullmatch(r'(.+), image (\d+)',s)
    if m: return f'{m[1]}, görsel {m[2]}'
    m=re.fullmatch(r'(.+): previous image',s)
    if m: return f'{m[1]}: önceki görsel'
    m=re.fullmatch(r'(.+): next image',s)
    if m: return f'{m[1]}: sonraki görsel'
    m=re.fullmatch(r'(.+) images, scrollable horizontally',s)
    if m: return f'{m[1]} görselleri, yatay kaydırılabilir'
    return None
